"""Small math helpers."""


def add(a, b):
    """Return a plus b."""
    return a + b


def subtract(a, b):
    """Return a minus b."""
    return a - b


def median(numbers):
    """Return the median of a list of numbers."""
    if not numbers:
        raise ValueError("median() not defined for empty list")
    numbers.sort()
    n = len(numbers)
    mid = n // 2
    if n % 2 == 0:
        return (numbers[mid - 1] + numbers[mid]) / 2.0
    else:
        return numbers[mid]
